svg.script:

(function() {
  var NS = "http://www.w3.org/2000/svg";

  function $(id) {
    return document.getElementById(id);
  }

  function R() {
    return Math.random();
  }

  function el(tag, attrs, parent, text) {
    var e = document.createElementNS(NS, tag);
    for (var k in attrs) e.setAttribute(k, attrs[k]);
    if (text !== undefined) e.textContent = text;
    if (parent) parent.appendChild(e);
    return e;
  }
  /* ---------- data ---------- */
  var COLORS = ["#38bdf8", "#f472b6", "#a3e635", "#fbbf24", "#c084fc", "#fb923c"];

  function col(v) {
    return COLORS[(v - 1) % COLORS.length];
  }
  var SAMPLES = [{
    p: [3, 1, 2, 4],
    a: [3, 4, 2, 2]
  }, {
    p: [1, 3, 2, 5, 4],
    a: [3, 3, 3, 5, 4]
  }];
  // Same logic as the accepted code: pos = value -> index in p, maxr = position of previous value.
  function build(s) {
    var n = s.p.length,
      pos = {},
      i;
    for (i = 0; i < n; i++) pos[s.p[i]] = i;
    var checks = [],
      maxr = 0,
      failed = false;
    for (i = 0; i < n; i++) {
      var ps = pos[s.a[i]],
        before = maxr;
      if (before > ps) {
        checks.push({
          i: i,
          pos: ps,
          before: before,
          fail: true,
          after: n
        });
        failed = true;
        break;
      }
      maxr = ps;
      checks.push({
        i: i,
        pos: ps,
        before: before,
        fail: false,
        after: maxr
      });
    }
    var steps = [{
      t: "intro"
    }];
    checks.forEach(function(c) {
      steps.push({
        t: "check",
        c: c
      });
    });
    steps.push({
      t: "verdict"
    });
    return {
      n: n,
      p: s.p,
      a: s.a,
      checks: checks,
      steps: steps,
      ok: !failed
    };
  }
  /* ---------- geometry ---------- */
  var PITCH = 76,
    CW = 64,
    CH = 52,
    CX = 310,
    AY = 150,
    PY = 310;

  function cx(n, i) {
    return CX - (n * PITCH - 12) / 2 + i * PITCH + CW / 2;
  }
  /* ---------- sound (Web Audio, synthesized inside this file) ---------- */
  var AC = null,
    MASTER = null,
    muted = false;
  var VOLUME = 4; // every voice is multiplied by this (1 = original loudness, 4 = four times louder)
  function ctx() {
    if (!AC) {
      var C = window.AudioContext || window.webkitAudioContext;
      if (C) {
        AC = new C();
        // A compressor keeps the louder mix from distorting when many voices overlap.
        var comp = AC.createDynamicsCompressor();
        comp.threshold.value = -18;
        comp.knee.value = 18;
        comp.ratio.value = 10;
        comp.attack.value = 0.003;
        comp.release.value = 0.25;
        var out = AC.createGain();
        out.gain.value = 1.3;
        comp.connect(out);
        out.connect(AC.destination);
        MASTER = comp;
      }
    }
    if (AC && AC.state === "suspended") AC.resume();
    return AC;
  }

  function lvl(g) {
    return Math.min(g * VOLUME, 0.95);
  }

  function tone(f, t0, d, type, g, f2) {
    var a = ctx();
    if (!a || muted) return;
    var o = a.createOscillator(),
      v = a.createGain(),
      T = a.currentTime + t0;
    o.type = type || "sine";
    o.frequency.setValueAtTime(f, T);
    if (f2) o.frequency.exponentialRampToValueAtTime(f2, T + d);
    v.gain.setValueAtTime(0.0001, T);
    v.gain.exponentialRampToValueAtTime(lvl(g || 0.15), T + 0.02);
    v.gain.exponentialRampToValueAtTime(0.0001, T + d);
    o.connect(v);
    v.connect(MASTER);
    o.start(T);
    o.stop(T + d + 0.05);
  }

  function noise(t0, d, g, f0, f1, type, q) {
    var a = ctx();
    if (!a || muted) return;
    var len = Math.max(1, Math.floor(a.sampleRate * d));
    var buf = a.createBuffer(1, len, a.sampleRate),
      data = buf.getChannelData(0);
    for (var i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    var src = a.createBufferSource();
    src.buffer = buf;
    var flt = a.createBiquadFilter(),
      T = a.currentTime + t0;
    flt.type = type || "lowpass";
    flt.frequency.setValueAtTime(f0, T);
    if (f1) flt.frequency.exponentialRampToValueAtTime(f1, T + d);
    flt.Q.value = q || 1;
    var v = a.createGain();
    v.gain.setValueAtTime(lvl(g), T);
    v.gain.exponentialRampToValueAtTime(0.0001, T + d);
    src.connect(flt);
    flt.connect(v);
    v.connect(MASTER);
    src.start(T);
    src.stop(T + d + 0.05);
  }
  // harsh, wobbling, rising screech (the irritating part)
  function screech(t0, d, g) {
    var a = ctx();
    if (!a || muted) return;
    var T = a.currentTime + t0;
    var o = a.createOscillator(),
      v = a.createGain(),
      l = a.createOscillator(),
      lg = a.createGain();
    o.type = "sawtooth";
    o.frequency.setValueAtTime(1500, T);
    o.frequency.linearRampToValueAtTime(2700, T + d);
    l.frequency.value = 38;
    lg.gain.value = 280;
    l.connect(lg);
    lg.connect(o.frequency);
    v.gain.setValueAtTime(0.0001, T);
    v.gain.exponentialRampToValueAtTime(lvl(g), T + 0.03);
    v.gain.exponentialRampToValueAtTime(0.0001, T + d);
    o.connect(v);
    v.connect(MASTER);
    o.start(T);
    l.start(T);
    o.stop(T + d + 0.05);
    l.stop(T + d + 0.05);
  }
  // glockenspiel-like bell: a few inharmonic partials
  function bell(f, t0, d, g) {
    tone(f, t0, d, "sine", g);
    tone(f * 2.756, t0, d * 0.5, "sine", g * 0.35);
    tone(f * 5.404, t0, d * 0.25, "sine", g * 0.15);
  }
  var SCALE = [261.63, 293.66, 329.63, 392.0, 440.0, 523.25, 587.33];
  var SPARKLE = [1568, 1760, 2093, 2349, 2637, 3136];

  function sfx(kind, p) {
    if (kind === "intro") {
      tone(392, 0, .25, "triangle", .12);
      tone(523.25, .15, .3, "triangle", .12);
    } else if (kind === "ok") {
      // charming: a bell note plus a little cascade of sparkles
      var f = SCALE[p % SCALE.length] * 2;
      bell(f, 0, .8, .12);
      tone(f * 3, .08, .18, "sine", .05);
      tone(f * 4, .16, .18, "sine", .04);
      tone(f * 5, .24, .22, "sine", .035);
    } else if (kind === "fail") {
      // explosion: boom + crackle + thump, then a wobbling screech, dissonant buzz and alarm beeps
      noise(0, .95, .35, 900, 60, "lowpass", .7);
      tone(70, 0, .7, "sine", .5, 30);
      noise(.05, .55, .15, 3200, 800, "bandpass", 3);
      screech(.12, .9, .07);
      tone(622, .15, .9, "square", .05);
      tone(440, .15, .9, "square", .05);
      for (var b = 0; b < 4; b++) tone(b % 2 ? 700 : 1000, .55 + b * .14, .12, "square", .06);
    } else if (kind === "die") {
      tone(480, p * .2, .28, "sine", .1, 140);
    } else if (kind === "yes") {
      [523.25, 659.25, 783.99, 1046.5].forEach(function(f, i) {
        bell(f, p + i * .12, .9, .12);
      });
      for (var j = 0; j < 10; j++) tone(SPARKLE[j % SPARKLE.length], p + .5 + j * .07, .25, "sine", .07);
    } else if (kind === "no") {
      tone(180, 0, .6, "sawtooth", .12, 60);
      tone(90, .1, .7, "sine", .18, 45);
      noise(0, .8, .12, 500, 80, "lowpass", .7);
    }
  }
  /* ---------- state ---------- */
  var S, k = 0,
    playing = false,
    timer = null,
    samp = 0,
    rid = 0;
  var STEP_MS = 3200;

  function deadValues() {
    var used = {};
    S.checks.forEach(function(c) {
      if (!c.fail) used[c.pos] = 1;
    });
    return S.p.filter(function(v, i) {
      return !used[i];
    });
  }

  function enter() {
    var st = S.steps[k];
    if (st.t === "intro") sfx("intro");
    else if (st.t === "check") {
      if (st.c.fail) sfx("fail");
      else sfx("ok", st.c.pos);
    } else if (S.ok) {
      var d = deadValues().length;
      for (var j = 0; j < d; j++) sfx("die", j);
      sfx("yes", d * .2 + .1);
    } else sfx("no");
  }

  function caption(st) {
    var n = S.n,
      last = S.checks.length - 1;
    if (st.t === "intro") {
      return ["p = " + S.p.join(" ") + "    a = " + S.a.join(" ") + "    n = " + n, "Map each a_i to its index in p. Keep maxr = index of the previous value.", "If maxr is ever larger than the next index, a value must cross another: no."];
    }
    if (st.t === "check") {
      var c = st.c,
        v = S.a[c.i];
      if (c.fail) {
        return ["i = " + c.i + ":  a_i = " + v + " sits at index " + c.pos + " in p.", "maxr before = " + c.before + ", and " + c.before + " > " + c.pos + ": the order is broken!", "maxr = n = " + n + " (failure marker), so the loop stops."];
      }
      var l3 = c.i === 0 ? "First element: nothing to compare with yet." : (c.pos === c.before ? "Same index as before: same segment, it just expands." : "Index moved right: a new segment, order kept.");
      return ["i = " + c.i + ":  a_i = " + v + " sits at index " + c.pos + " in p.", "maxr before = " + c.before + ", is " + c.before + " > " + c.pos + "? No, so maxr = " + c.pos + ".",
        l3
      ];
    }
    if (!S.ok) {
      var fi = S.checks[last].i;
      return ["Value " + S.a[fi - 1] + " is to the right of " + S.a[fi] + " in p, but a needs it to the left.", "That would require a crossing, and copies can never cross.", "maxr = n, so (maxr < n) is false and it prints \u201Cno\u201D."];
    }
    var dead = deadValues();
    return ["Positions along a: " + S.checks.map(function(c) {
        return c.pos;
      }).join(", ") + ". They never decrease.",
      dead.length ? "Values " + dead.join(" and ") + " never appear in a, so they die. The others expand." : "Every value survives; the blocks only change length.", "maxr = " + S.checks[last].after + " < n = " + S.n + ", so it prints \u201Cyes\u201D."
    ];
  }
  /* ---------- effects ---------- */
  var fx = $("fx");
  var TW_COLORS = ["#fef3c7", "#fde68a", "#ffffff", "#a5f3fc", "#fbcfe8"];
  var STAR = "M0 -10Q2 -2 10 0Q2 2 0 10Q-2 2 -10 0Q-2 -2 0 -10Z";
  var DIAMOND = "M0 -10L7 0L0 10L-7 0Z";

  function explosion(X, Y) {
    var g = el("g", {}, fx),
      i, c;
    el("circle", {
      cx: X,
      cy: Y,
      r: 16,
      fill: "#fff3c4",
      class: "flash"
    }, g);
    c = el("circle", {
      cx: X,
      cy: Y,
      r: 14,
      class: "ring"
    }, g);
    c = el("circle", {
      cx: X,
      cy: Y,
      r: 14,
      class: "ring"
    }, g);
    c.style.animationDelay = ".18s";
    for (i = 0; i < 16; i++) {
      c = el("circle", {
        cx: X,
        cy: Y,
        r: 10 + R() * 14,
        fill: "url(#smokeGrad)",
        filter: "url(#soft)",
        class: "smoke"
      }, g);
      c.style.setProperty("--dx", ((R() - .5) * 140) + "px");
      c.style.setProperty("--dy", (-30 - R() * 100) + "px");
      c.style.setProperty("--s", String(3 + R() * 3));
      c.style.animationDelay = (R() * .35) + "s";
      c.style.animationDuration = (1.8 + R() * 1.2) + "s";
    }
    for (i = 0; i < 14; i++) {
      var ang = R() * Math.PI * 2,
        dist = 50 + R() * 80;
      c = el("circle", {
        cx: X,
        cy: Y,
        r: 2.5 + R() * 2,
        fill: R() < .5 ? "#fb923c" : "#fde047",
        class: "spark"
      }, g);
      c.style.setProperty("--dx", (Math.cos(ang) * dist) + "px");
      c.style.setProperty("--dy", (Math.sin(ang) * dist) + "px");
    }
  }

  function lingeringSmoke(X, Y) {
    var g = el("g", {}, fx);
    for (var i = 0; i < 7; i++) {
      var c = el("circle", {
        cx: X,
        cy: Y,
        r: 12 + R() * 10,
        fill: "url(#smokeGrad)",
        filter: "url(#soft)",
        class: "smoke-loop"
      }, g);
      c.style.setProperty("--dx", ((R() - .5) * 60) + "px");
      c.style.setProperty("--dy", (-40 - R() * 60) + "px");
      c.style.setProperty("--s", String(2.5 + R() * 1.5));
      c.style.animationDelay = (i * .45) + "s";
    }
  }
  // areas: [{x, y, rx, ry}], count twinkles spread across them
  function twinkles(areas, count, loop) {
    var g = el("g", {
      filter: "url(#glow)"
    }, fx);
    for (var i = 0; i < count; i++) {
      var ar = areas[i % areas.length];
      var x = ar.x + (R() - .5) * 2 * ar.rx,
        y = ar.y + (R() - .5) * 2 * ar.ry;
      var holder = el("g", {
        transform: "translate(" + x + " " + y + ")"
      }, g);
      var p = el("path", {
        d: R() < .5 ? STAR : DIAMOND,
        fill: TW_COLORS[Math.floor(R() * TW_COLORS.length)],
        class: "tw"
      }, holder);
      p.style.setProperty("--s", String(.5 + R() * .9));
      p.style.animationDuration = (.9 + R() * .9) + "s";
      p.style.animationDelay = (R() * 1.2) + "s";
      p.style.animationIterationCount = loop ? "infinite" : "2";
    }
  }
  /* ---------- render ---------- */
  var dyn = $("dyn");

  function T(x, y, s, fill, bold) {
    el("text", {
      x: x,
      y: y,
      "text-anchor": "middle",
      "font-size": 13,
      fill: fill,
      "font-weight": bold ? 700 : 400
    }, dyn, s);
  }

  function render() {
    rid++;
    var myId = rid,
      n = S.n,
      st = S.steps[k],
      last = S.checks.length - 1,
      i, j;
    var isCheck = st.t === "check",
      final = st.t === "verdict";
    var upto = isCheck ? st.c.i : (final ? last : -1);
    var failShown = (isCheck && st.c.fail) || (final && !S.ok);
    var fi = S.ok ? -1 : S.checks[last].i;
    var used = {};
    S.checks.forEach(function(c) {
      if (!c.fail) used[c.pos] = 1;
    });
    dyn.textContent = "";
    fx.textContent = "";
    dyn.removeAttribute("class");
    /* where the two lines cross (only when the order is broken) */
    var cross = null;
    if (failShown && fi > 0) {
      var A0 = cx(n, fi - 1),
        A1 = cx(n, S.checks[fi - 1].pos),
        B0 = cx(n, fi),
        B1 = cx(n, S.checks[fi].pos);
      var den = (A1 - A0) - (B1 - B0);
      if (den !== 0) {
        var tt = (B0 - A0) / den;
        cross = {
          X: A0 + (A1 - A0) * tt,
          Y: AY + CH + tt * (PY - AY - CH)
        };
      }
    }
    /* lines from a_i to its index in p */
    var lines = el("g", {}, dyn);
    for (j = 0; j <= upto; j++) {
      var c = S.checks[j],
        cur = isCheck && j === st.c.i;
      var inv = failShown && (j === fi || j === fi - 1);
      var x1 = cx(n, j),
        y1 = AY + CH,
        x2 = cx(n, c.pos),
        y2 = PY;
      var lc = inv ? "#ef4444" : col(S.a[j]);
      var pth = el("path", {
        d: "M" + x1 + " " + y1 + "L" + x2 + " " + y2,
        pathLength: 1,
        fill: "none",
        stroke: lc,
        "stroke-width": (cur || inv) ? 4 : 2.5,
        "stroke-linecap": "round",
        opacity: (cur || inv) ? 1 : (final ? 0.85 : 0.5)
      }, lines);
      if (cur) pth.setAttribute("class", "draw");
      el("circle", {
        cx: x2,
        cy: y2,
        r: 5,
        fill: lc
      }, lines);
    }
    /* p cells */
    for (i = 0; i < n; i++) {
      var pv = S.p[i],
        dead = final && S.ok && !used[i];
      var g = el("g", {
        opacity: dead ? 0.3 : 1
      }, dyn);
      el("rect", {
        x: cx(n, i) - CW / 2,
        y: PY,
        width: CW,
        height: CH,
        rx: 10,
        fill: col(pv),
        "fill-opacity": 0.22,
        stroke: col(pv),
        "stroke-width": 2,
        "stroke-dasharray": dead ? "5 4" : "none"
      }, g);
      el("text", {
        x: cx(n, i),
        y: PY + 35,
        "text-anchor": "middle",
        class: "val"
      }, g, String(pv));
      el("text", {
        x: cx(n, i),
        y: PY + CH + 16,
        "text-anchor": "middle",
        class: "idx"
      }, dyn, String(i));
      if (dead) el("text", {
        x: cx(n, i),
        y: PY - 8,
        "text-anchor": "middle",
        "font-size": 12,
        fill: "#94a3b8"
      }, dyn, "dies \u2715");
    }
    /* a cells */
    for (i = 0; i < n; i++) {
      var av = S.a[i],
        curA = isCheck && i === st.c.i,
        done = i <= upto;
      el("rect", {
        x: cx(n, i) - CW / 2,
        y: AY,
        width: CW,
        height: CH,
        rx: 10,
        fill: col(av),
        "fill-opacity": done ? 0.3 : 0.12,
        stroke: curA ? "#ffffff" : col(av),
        "stroke-width": curA ? 4 : 2
      }, dyn);
      el("text", {
        x: cx(n, i),
        y: AY + 35,
        "text-anchor": "middle",
        class: "val",
        opacity: done ? 1 : 0.55
      }, dyn, String(av));
      el("text", {
        x: cx(n, i),
        y: AY - 8,
        "text-anchor": "middle",
        class: "idx"
      }, dyn, String(i));
      if (curA) {
        el("path", {
          d: "M" + (cx(n, i) - 9) + " 98L" + (cx(n, i) + 9) + " 98L" + cx(n, i) + " 112Z",
          fill: "#ffffff"
        }, dyn);
        el("text", {
          x: cx(n, i) + 14,
          y: 111,
          "font-size": 13,
          "font-weight": 700
        }, dyn, "i = " + i);
      }
    }
    /* blocks under a when the answer is yes: equal neighbours share a segment */
    if (final && S.ok) {
      var l = 0;
      for (i = 1; i <= n; i++) {
        if (i === n || S.a[i] !== S.a[l]) {
          el("rect", {
            x: cx(n, l) - CW / 2,
            y: AY + CH + 4,
            width: cx(n, i - 1) - cx(n, l) + CW,
            height: 6,
            rx: 3,
            fill: col(S.a[l])
          }, dyn);
          l = i;
        }
      }
    }
    /* crossing marker */
    if (cross) {
      var cg = el("g", {
        class: "pop"
      }, dyn);
      el("circle", {
        cx: cross.X,
        cy: cross.Y,
        r: 11,
        fill: "none",
        stroke: "#ef4444",
        "stroke-width": 3
      }, cg);
      el("text", {
        x: cross.X + 18,
        y: cross.Y + 5,
        "font-size": 14,
        "font-weight": 700,
        fill: "#fca5a5",
        class: "halo"
      }, cg, "crossing!");
    }
    /* maxr marker */
    var mB, mA, mFail = false;
    if (st.t === "intro") {
      mB = 0;
      mA = 0;
    } else if (isCheck) {
      mB = st.c.before;
      mA = st.c.fail ? n : st.c.after;
      mFail = st.c.fail;
    } else {
      mB = S.ok ? S.checks[last].after : n;
      mA = mB;
      mFail = !S.ok;
    }
    var mc = mFail ? "#ef4444" : "#f59e0b";
    if (mFail) el("text", {
      x: cx(n, n),
      y: PY + CH + 16,
      "text-anchor": "middle",
      class: "idx"
    }, dyn, "n");
    var mg = el("g", {}, dyn);
    mg.style.transform = "translate(" + cx(n, mB) + "px,0px)";
    mg.style.transition = "transform .9s ease-in-out";
    el("path", {
      d: "M-9 404L9 404L0 390Z",
      fill: mc
    }, mg);
    el("text", {
      x: 0,
      y: 422,
      "text-anchor": "middle",
      "font-size": 13,
      "font-weight": 700,
      fill: mc
    }, mg, mFail ? "maxr = n = " + n : "maxr = " + mA);
    if (mB !== mA) {
      setTimeout(function() {
        if (myId === rid) mg.style.transform = "translate(" + cx(n, mA) + "px,0px)";
      }, 60);
    }
    /* table rows */
    for (var r = 0; r <= upto; r++) {
      var cc = S.checks[r],
        yy = 164 + r * 30;
      if (isCheck && r === st.c.i) el("rect", {
        x: 610,
        y: yy,
        width: 262,
        height: 26,
        rx: 6,
        fill: "#334155"
      }, dyn);
      var ty = yy + 18;
      T(628, ty, String(cc.i), "#e2e8f0");
      T(668, ty, String(S.a[r]), col(S.a[r]), true);
      T(722, ty, String(cc.pos), "#e2e8f0");
      T(788, ty, String(cc.before), "#e2e8f0");
      if (cc.fail) T(852, ty, "\u2717 " + cc.before + ">" + cc.pos, "#ef4444", true);
      else T(852, ty, "\u2713", "#22c55e", true);
    }
    el("text", {
      x: 622,
      y: 348,
      "font-size": 11,
      fill: "#94a3b8"
    }, dyn, "n = " + n + ".  Failure marker: maxr = n.");
    /* verdict panel */
    var pc = final ? (S.ok ? "#22c55e" : "#ef4444") : "#475569";
    el("rect", {
      x: 602,
      y: 378,
      width: 278,
      height: 138,
      rx: 16,
      fill: "#1e293b",
      stroke: pc,
      "stroke-width": final ? 3 : 1.5
    }, dyn);
    if (final) {
      el("text", {
        x: 741,
        y: 444,
        "text-anchor": "middle",
        "font-size": 54,
        "font-weight": 800,
        fill: pc,
        class: "pop"
      }, dyn, S.ok ? "YES" : "NO");
      el("text", {
        x: 741,
        y: 474,
        "text-anchor": "middle",
        "font-size": 14
      }, dyn, "prints \u201C" + (S.ok ? "yes" : "no") + "\u201D");
      el("text", {
        x: 741,
        y: 498,
        "text-anchor": "middle",
        "font-size": 12,
        fill: "#94a3b8"
      }, dyn, S.ok ? "positions never decrease" : "order broken: values would cross");
    } else {
      el("text", {
        x: 741,
        y: 444,
        "text-anchor": "middle",
        "font-size": 54,
        "font-weight": 800,
        fill: "#64748b"
      }, dyn, "?");
      el("text", {
        x: 741,
        y: 474,
        "text-anchor": "middle",
        "font-size": 13,
        fill: "#94a3b8"
      }, dyn, "verdict pending");
    }
    /* narration */
    var cap = caption(st);
    for (var q = 0; q < cap.length; q++) {
      el("text", {
        x: 48,
        y: 460 + q * 20,
        "font-size": 14,
        "font-weight": q === 0 ? 700 : 400,
        fill: q === 0 ? "#ffffff" : "#cbd5e1"
      }, dyn, cap[q]);
    }
    /* progress dots */
    for (var s = 0; s < S.steps.length; s++) {
      el("circle", {
        cx: 616 + s * 22,
        cy: 545,
        r: s === k ? 6 : 4,
        fill: s <= k ? "#38bdf8" : "#475569"
      }, dyn);
    }
    el("text", {
      x: 616 + S.steps.length * 22 + 6,
      y: 549,
      "font-size": 11,
      fill: "#94a3b8"
    }, dyn, "step " + k + " / " + (S.steps.length - 1));
    /* effects */
    if (isCheck && st.c.fail && cross) {
      explosion(cross.X, cross.Y);
      void dyn.getBoundingClientRect(); // restart the shake animation
      dyn.setAttribute("class", "shake");
    } else if (final && !S.ok && cross) {
      lingeringSmoke(cross.X, cross.Y);
    } else if (isCheck && !st.c.fail) {
      twinkles([{
        x: cx(n, st.c.pos),
        y: PY + CH / 2,
        rx: 46,
        ry: 36
      }, {
        x: cx(n, st.c.i),
        y: AY + CH / 2,
        rx: 46,
        ry: 36
      }], 10, false);
    } else if (final && S.ok) {
      var areas = [];
      for (i = 0; i < n; i++) {
        areas.push({
          x: cx(n, i),
          y: AY + CH / 2,
          rx: 42,
          ry: 36
        });
        if (used[i]) areas.push({
          x: cx(n, i),
          y: PY + CH / 2,
          rx: 42,
          ry: 36
        });
      }
      twinkles(areas, 30, true);
    }
  }
  /* ---------- controls ---------- */
  function lastStep() {
    return S.steps.length - 1;
  }

  function setPlaying(v) {
    playing = v;
    $("playLbl").textContent = v ? "\u275A\u275A Pause" : "\u25B6 Play";
    if (!v && timer) {
      clearTimeout(timer);
      timer = null;
    }
  }

  function go(nk) {
    k = nk;
    render();
    enter();
  }

  function tick() {
    if (!playing) return;
    if (k >= lastStep()) {
      setPlaying(false);
      return;
    }
    go(k + 1);
    timer = setTimeout(tick, STEP_MS);
  }

  function startPlay() {
    if (k >= lastStep()) {
      k = 0;
      render();
    }
    setPlaying(true);
    if (k === 0) enter();
    timer = setTimeout(tick, STEP_MS);
  }

  function load(idx) {
    setPlaying(false);
    samp = idx;
    S = build(SAMPLES[idx]);
    k = 0;
    $("tab0").setAttribute("class", "btn tab" + (idx === 0 ? " active" : ""));
    $("tab1").setAttribute("class", "btn tab" + (idx === 1 ? " active" : ""));
    render();
  }
  $("btnPlay").addEventListener("click", function() {
    ctx();
    if (playing) setPlaying(false);
    else startPlay();
  });
  $("btnStep").addEventListener("click", function() {
    ctx();
    setPlaying(false);
    if (k < lastStep()) go(k + 1);
  });
  $("btnRestart").addEventListener("click", function() {
    ctx();
    setPlaying(false);
    k = 0;
    render();
    startPlay();
  });
  $("btnSound").addEventListener("click", function() {
    muted = !muted;
    $("sndLbl").textContent = muted ? "Sound: off" : "Sound: on";
    if (!muted) {
      ctx();
      bell(880, 0, .5, .1);
    }
  });
  $("tab0").addEventListener("click", function() {
    load(0);
  });
  $("tab1").addEventListener("click", function() {
    load(1);
  });
  load(0);
})();
